abstract class Handler {
  protected Handler siguiente;
  public void setSiguiente(Handler h) { this.siguiente = h; }
  public void manejar(Peticion p) {
    if (siguiente != null) siguiente.manejar(p);
  }
}
class AuthHandler extends Handler {
  public void manejar(Peticion p) {
    if (!p.autenticada()) { log("Rechazada"); return; }
    super.manejar(p);
  }
} // Chain of Responsibility

