interface Command {
  void execute();
  void undo();
}

public class TextCommand {
  private final Editor editor;
  private final String previousText;
  public void execute() { editor.insertText(text); }
  public void undo() { editor.setText(previousText); }
} // Command con undo

public class CommandHistory {
  private final Deque<Command> stack = new ArrayDeque<>();
  public void execute(Command cmd) { cmd.execute(); stack.push(cmd); }
  public void undo() { if (!stack.isEmpty()) stack.pop().undo(); }
} // Cola de comandos

