interface Visitor<T> {
  void visit(Producto p);
  void visit(Servicio s);
  void visit(Descuento d);
}

class CostoVisitor implements Visitor<Double> {
  double total = 0;
  public void visit(Producto p) { total += p.getPrecio(); }
  public void visit(Servicio s) { total += s.getTarifa(); }
  public void visit(Descuento d) { total -= d.getMonto(); }
} // Visitor que calcula costo

interface ElementoCarrito {
  void accept(Visitor visitor);
}

class Producto implements ElementoCarrito {
  public void accept(Visitor v) { v.visit(this); }
} // accept para double dispatch

public class Editor {
  private String texto = "";
  private final CommandHistory historial = new CommandHistory();
  public void ejecutar(Command cmd) { historial.execute(cmd); }
  public void deshacer() { historial.undo(); }
} // Editor con undo/redo

