  public CharacterFlyweight get(char c) {
    return pool.computeIfAbsent(c, CharacterFlyweight::new);
  }
} // Flyweight factory

class CharacterFlyweight {
  private final char character;
  public CharacterFlyweight(char c) { this.character = c; }
  public void render(int row, int col, String font) {
    System.out.println("Draw '" + character + "' at " + row + "," + col + " in " + font);
  }
} // Flyweight inmutable

